def define_MP_model(task, paths_list):
    task.paths = paths_list # list of (C_i_1, S_i, C_i_2)
    return task

def is_edf_feasible(jobs, window_start, window_end):
    total_demand = 0
    for job in jobs:
        if job.arrival >= window_start and job.deadline <= window_end:
            total_demand += job.C
    return total_demand <= (window_end - window_start)

def dbf_FRD(t, D_i_1, task):
    val1 = compute_dbf_pattern1(t, D_i_1, task)
    val2 = compute_dbf_pattern2(t, D_i_1, task)
    return max(val1, val2)

def dbf_IUB(t, D_i_1, task):
    # G_I_i is a helper for the 'last' partial period
    term1 = (t // task.T_i) * task.C_max_i + G_I_i(t % task.T_i, D_i_1)
    # dbf_I_2_i handles the offset release of segment 2
    term2 = compute_dbf_I_2(t, D_i_1, task)
    return max(term1, term2)

def dbf_MP(t, D_i_1, task):
    d1 = compute_dbf_MP_1(t, D_i_1, task)
    d2_max = 0
    for path_j in task.paths:
        d2_j = compute_dbf_MP_2_j(t, D_i_1, path_j)
        d2_max = max(d2_max, d2_j)
    return max(d1, d2_max)

def dbf_clairvoyant(t, task):
    # G_clair_i uses max over paths for segment 1 demand
    d1 = (t // task.T_i) * task.C_max_i + G_clair_i(t % task.T_i)
    d2_max = 0
    for path_j in task.paths:
        d2_j = compute_dbf_clair_2_j(t, path_j)
        d2_max = max(d2_max, d2_j)
    return max(d1, d2_max)

def is_FRD_schedulable(task_set, deadlines_D1):
    for t in range(0, max_test_limit):
        total_demand = 0
        for i, task in enumerate(task_set):
            total_demand += dbf_FRD(t, deadlines_D1[i], task)
        if total_demand > t:
            return False
    return True

def is_hybrid_schedulable(task_set, model_type):
    for t in range(0, max_test_limit):
        total_demand = 0
        for task in task_set:
            if model_type == 'IUB':
                total_demand += dbf_IUB(t, task.D_i_1, task)
            elif model_type == 'MP':
                total_demand += dbf_MP(t, task.D_i_1, task)
            elif model_type == 'Clairvoyant':
                total_demand += dbf_clairvoyant(t, task)
        if total_demand > t:
            return False
    return True
